# Generated by `cargo xtask formula` in https://github.com/michel-onstein/acs for each release
# (scripts/update-tap.sh): edit the generator there, not this file.
# acs-version: 0.23.0
#
# acs releases are signed; SHA256SUMS.sig is checked against this key:
#   ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAILbxQW5C9X7CdwcQ4bab0gsQi4Evk2xfgmI/972dlHCb acs release signing
# Verify a release by hand:
#   printf 'releases@acs namespaces="acs-release" %s\n' "$key" > allowed
#   ssh-keygen -Y verify -f allowed -I releases@acs -n acs-release -s SHA256SUMS.sig < SHA256SUMS
class Acs < Formula
  desc "Persistent, reconnecting remote shells over ssh"
  homepage "https://github.com/michel-onstein/acs"
  license "MIT"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/0.23.0/acs-0.23.0-aarch64-apple-darwin.tar.gz"
      sha256 "9ab34cf0e304ee91014947674fd84a73e7d44210cf7423bed37e238f6c8e8af4"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/0.23.0/acs-0.23.0-x86_64-apple-darwin.tar.gz"
      sha256 "4ca57da8ebdef1f1a28e06d33545291a6c0dc52e3482b10c0bd18642d579a8c7"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/0.23.0/acs-0.23.0-aarch64-unknown-linux-musl.tar.gz"
      sha256 "8b217a4227fd9db905b1d7efec52c54b75806a900cebf8083aaca8b8bb5dc891"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/0.23.0/acs-0.23.0-x86_64-unknown-linux-musl.tar.gz"
      sha256 "c591607241cfad0f1b9d0f1bcc6ae6e29a982f342c31c238b7206b0ff82cdd6a"
    end
  end

  def install
    bin.install "acs"
    bin.install_symlink "acs" => "acscp"
  end

  test do
    out = shell_output("#{bin}/acs --version")
    assert_match "acs #{version} ", out
    remotes = out[/^installs remotes: (.*)$/, 1].to_s.split(", ")
    assert_includes remotes, "x86_64-unknown-linux-musl"
    assert_includes remotes, "aarch64-unknown-linux-musl"
    assert_match "acs #{version} ", shell_output("#{bin}/acscp --version")
  end
end
